-- +goose Up
CREATE TABLE "vulnerability_candidate_items" ("id" INTEGER PRIMARY KEY AUTOINCREMENT,"proof_id" TEXT NOT NULL,"advisory" TEXT NOT NULL,"package" TEXT NOT NULL,"installed" TEXT NOT NULL,"fixed" TEXT NOT NULL,"severity" TEXT NOT NULL,"class" TEXT NOT NULL,"type" TEXT NOT NULL,FOREIGN KEY (proof_id) REFERENCES vulnerability_candidate_proofs(id) ON DELETE CASCADE,CHECK (severity IN ('UNKNOWN','LOW','MEDIUM','HIGH','CRITICAL')),UNIQUE (proof_id,advisory,package,installed,class,type));
CREATE TABLE "vulnerability_candidate_proofs" ("id" TEXT NOT NULL,"repository" TEXT NOT NULL,"manifest_digest" TEXT NOT NULL,"config_digest" TEXT NOT NULL,"platform" TEXT NOT NULL,"scanner_version" TEXT NOT NULL,"db_version" INTEGER NOT NULL,"db_updated_at" datetime NOT NULL,"policy" TEXT NOT NULL,"completed_at" datetime NOT NULL,PRIMARY KEY ("id"),CHECK (platform = 'linux/amd64'),CHECK (db_version = 2),CHECK (length(manifest_digest) = 71 AND substr(manifest_digest,1,7) = 'sha256:' AND substr(manifest_digest,8) NOT GLOB '*[^a-f0-9]*'),CHECK (length(config_digest) = 71 AND substr(config_digest,1,7) = 'sha256:' AND substr(config_digest,8) NOT GLOB '*[^a-f0-9]*'),UNIQUE (repository,manifest_digest,platform,scanner_version,db_updated_at,policy));
CREATE TABLE "vulnerability_candidate_runs" ("id" TEXT NOT NULL,"activity_id" TEXT NOT NULL,"trigger" TEXT NOT NULL,"status" TEXT NOT NULL,"started_at" datetime NOT NULL,"completed_at" datetime,"targets" INTEGER NOT NULL,"scanned" INTEGER NOT NULL,"cached" INTEGER NOT NULL,"failed" INTEGER NOT NULL,"deferred" INTEGER NOT NULL,"intelligence" TEXT NOT NULL,PRIMARY KEY ("id"),CHECK (trigger IN ('manual','automatic')),CHECK (status IN ('running','completed','partial','failed','cancelled','interrupted')),CHECK (targets >= 0 AND scanned >= 0 AND cached >= 0 AND failed >= 0 AND deferred >= 0),CHECK (intelligence IN ('available','unavailable')),CHECK ((status = 'running') = (completed_at IS NULL)),UNIQUE (activity_id));
CREATE TABLE "vulnerability_candidate_targets" ("id" TEXT NOT NULL,"run_id" TEXT NOT NULL,"repository" TEXT NOT NULL,"manifest_digest" TEXT NOT NULL,"config_digest" TEXT NOT NULL,"platform" TEXT NOT NULL,"consumer" TEXT NOT NULL,"state" TEXT NOT NULL,"attempt_id" TEXT NOT NULL,"proof_id" TEXT,"error_code" TEXT NOT NULL,PRIMARY KEY ("id"),FOREIGN KEY (run_id) REFERENCES vulnerability_candidate_runs(id) ON DELETE CASCADE,FOREIGN KEY (proof_id) REFERENCES vulnerability_candidate_proofs(id) ON DELETE SET NULL,CHECK (state IN ('queued','running','completed','failed','cancelled','interrupted','deferred')),CHECK (platform IN ('','linux/amd64')),CHECK (manifest_digest = '' OR (length(manifest_digest) = 71 AND substr(manifest_digest,1,7) = 'sha256:' AND substr(manifest_digest,8) NOT GLOB '*[^a-f0-9]*')),CHECK ((state NOT IN ('queued','running','completed','deferred')) OR (repository <> '' AND manifest_digest <> '' AND platform <> '')),UNIQUE (run_id,consumer),CHECK ("consumer" IS NULL OR json_valid("consumer")));
CREATE INDEX `idx_vulnerability_candidate_items_proof_id` ON `vulnerability_candidate_items`(`proof_id`);
CREATE INDEX `idx_vulnerability_candidate_proofs_completed_at` ON `vulnerability_candidate_proofs`(`completed_at`);
CREATE INDEX `idx_vulnerability_candidate_targets_run_id` ON `vulnerability_candidate_targets`(`run_id`);
